.video-container iframe {
  max-width: 100%
}

.breadcrumb {
  background: none;
  padding: 0
}

button.close:focus {
  outline: none
}

.close {
  text-shadow: none
}

.dropdown-toggle {
  cursor: pointer
}

.dropdown-menu {
  border: 1px solid #e6e6e6;
  border-radius: 0;
  background-clip: padding-box;
  box-shadow: 0 2px 3px rgba(0, 0, 0, .1);
  cursor: default
}

.dropdown-menu>li {
  margin-bottom: 0;
  font-size: 13px
}

.dropdown-menu>li>a {
  padding: 10px 15px;
  color: #494d55
}

.dropdown-menu>li>a:hover {
  background: #f9f9fb
}

.dropdown-menu>li>a .icon {
  vertical-align: middle;
  font-size: 20px;
  display: inline-block;
  margin-right: 5px
}

.dropdown-menu .dropdown-footer {
  background: #f9f9fb;
  color: #616670;
  padding: 15px;
  text-align: center
}

.dropdown-menu .dropdown-footer a {
  color: #616670
}

.dropdown-menu .dropdown-footer a:hover {
  color: #494d55
}

.pace {
  -webkit-pointer-events: none;
  pointer-events: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none
}

.pace-inactive {
  display: none
}

.pace .pace-progress {
  background: #40babd;
  position: fixed;
  z-index: 5;
  top: 0;
  right: 100%;
  width: 100%;
  height: 2px
}

.theme-2 .pace .pace-progress {
  background: #6dbd63
}

.theme-3 .pace .pace-progress {
  background: #497cb1
}

.theme-4 .pace .pace-progress {
  background: #ec6952
}

.header {
  background: #fff;
  z-index: 2;
  box-shadow: 0 0 4px rgba(0, 0, 0, .05)
}

.header,
.header .branding {
  position: relative;
  height: 80px
}

.header .branding {
  background: #40babd;
  float: left;
  transition: width .4s cubic-bezier(.215, .61, .355, 1);
  width: 180px;
  overflow: hidden;
  will-change: width
}

.theme-2 .header .branding {
  background: #6dbd63
}

.theme-3 .header .branding {
  background: #497cb1
}

.theme-4 .header .branding {
  background: #ec6952
}

.compact:not(.nav-toggled) .header .branding,
.mobile.nav-toggled .header .branding,
.nav-toggled:not(.compact):not(.mobile) .header .branding {
  width: 40px
}

.mobile:not(.nav-toggled) .header .branding {
  width: 0;
  top: -2px
}

.header .branding .logo-icon {
  position: relative;
  width: 30px;
  height: 30px
}

.header .branding .logo {
  font-size: 28px;
  margin: 0;
  padding-top: 20px;
  text-transform: uppercase;
  font-weight: 600
}

.header .branding .logo .highlight {
  font-weight: 800
}

.header .branding .logo a {
  color: #fff;
  white-space: nowrap
}

.header .branding .logo a:hover {
  text-decoration: none
}

.header .branding .logo .nav-label {
  white-space: nowrap
}

.compact:not(.nav-toggled) .header .branding .logo .nav-label,
.mobile .header .branding .logo .nav-label,
.nav-toggled:not(.compact):not(.mobile) .header .branding .logo .nav-label {
  display: none
}

.header .topbar {
  padding: 15px;
  display: block;
  height: 80px
}

.header .topbar .icon {
  color: #9499a3
}

.header .main-nav-toggle {
  display: inline-block;
  float: left;
  background: none;
  border: none;
  padding: 12px;
  margin-top: 5px;
  margin-left: 15px;
  position: relative
}

.header .main-nav-toggle .icon {
  position: absolute;
  left: 2px;
  top: 13px;
  color: #40babd;
  font-weight: 700;
  transition: transform .4s cubic-bezier(.215, .61, .355, 1)
}

.theme-2 .header .main-nav-toggle .icon {
  color: #6dbd63
}

.theme-3 .header .main-nav-toggle .icon {
  color: #497cb1
}

.theme-4 .header .main-nav-toggle .icon {
  color: #ec6952
}

.compact .header .main-nav-toggle .icon,
.mobile .header .main-nav-toggle .icon,
.nav-toggled .header .main-nav-toggle .icon {
  transform: rotate(180deg)
}

.compact.nav-toggled .header .main-nav-toggle .icon,
.mobile.nav-toggled .header .main-nav-toggle .icon {
  transform: rotate(0)
}

.header .main-nav-toggle .icon-bar {
